                  >
                    {post.title}
                  </Link>
                </li>
              ))}
            </ul>
          ) : (
            posts && <p style={{ color: '#6b7280', fontStyle: 'italic' }}>No posts found. Please run the seed command.</p>
          )}
        </div>
      </main>
    </div>
  )
}
